import math
from typing import List
from collections import defaultdict

def create_tree(a: List[int]):
    n = len(a)
    tree = [0] * (n + 1)

    for i in range(1, n + 1):
        tree[i] = a[i - 1]
        for j in range(i + math.log2(i) + 1, n + 1):
            tree[j] += tree[i]

    return tree

def query_sum(tree: List[int], l: int, r: int) -> int:
    return sum(tree[i] for i in range(l, r + 1)) - sum(tree[i] for i in range(1, l))

def solve(a: List[int], k: int) -> int:
    n = len(a)
    dp = defaultdict(lambda: float('inf'))
    dp[0] = 0

    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + abs(a[i - 1] - a[i])

    tree = create_tree(a)

    for i in range(1, n + 1):
        if i + k - 1 < n:
            dp[i + k] = min(dp[i + k], dp[i] + query_sum(tree, i + 1, i + k))

    return min(dp[n])

