def sieve_of_eratosthenes(limit):
    primes = []
    sieve = [True] * (limit + 1)
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            primes.append(i)
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    for i in range(limit, 0, -1):
        if sieve[i]:
            primes.append(i)
    return primes

def find(x, parent):
    if parent[x] != x:
        parent[x] = find(parent[x], parent)
    return parent[x]

def union(x, y, size, parent):
    x_root, y_root = find(x, parent), find(y, parent)
    if x_root == y_root:
        return
    if size[x_root] < size[y_root]:
        parent[x_root] = y_root
        size[y_root] += size[x_root]
    else:
        parent[y_root] = x_root
        size[x_root] += size[y_root]

def solve(n):
    primes = sieve_of_eratosthenes(n + 1)
    parents, sizes = list(count(0)), [1] * n
    for i in range(n):
        for p in primes:
            if p > n:
                break
            if gcd(p, i + 1) == 1:
                x, y = i, (i + 1) // p
                if find(x) != find(y):
                    union(x, y, sizes, parents)
    permutation = list(chain.from_iterable(sorted(filter(lambda x: parents[x] == x, range(n)), key=lambda x: parents[x])))
    return permutation

